from pathlib import Path
from copy import deepcopy
import json, hashlib, re
from docx import Document
from docx.shared import Pt, RGBColor
from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.opc.constants import RELATIONSHIP_TYPE as RT

BASE=Path(__file__).resolve().parent
OUT=BASE/'output';OUT.mkdir(exist_ok=True)
changes=[]
def replace(p,text):
    old=p.text
    if old==text:return
    style=deepcopy(p.runs[0]._element.rPr) if p.runs and p.runs[0]._element.rPr is not None else None
    p.clear();r=p.add_run(text)
    if style is not None:r._element.insert(0,style)
    changes.append({'old':old,'new':text})
def par(d,i,start,text):
    p=d.paragraphs[i];assert p.text.startswith(start),(i,p.text,start);replace(p,text)
def cell(d,t,r,c,text):replace(d.tables[t].cell(r,c).paragraphs[0],text)
def link(p,label,url):
    h=OxmlElement('w:hyperlink');h.set(qn('r:id'),p.part.relate_to(url,RT.HYPERLINK,is_external=True))
    r=OxmlElement('w:r');pr=OxmlElement('w:rPr');color=OxmlElement('w:color');color.set(qn('w:val'),'333333');pr.append(color);u=OxmlElement('w:u');u.set(qn('w:val'),'single');pr.append(u);r.append(pr)
    t=OxmlElement('w:t');t.text=label;r.append(t);h.append(r);p._p.append(h)
LAWS={
 '328':('Встречное исполнение','https://www.consultant.ru/document/cons_doc_LAW_5142/331033e3d6e7b72213bd9903b03e29dfb9e608fe/'),
 '719':('Неисполнение обязанностей заказчиком','https://www.consultant.ru/document/cons_doc_LAW_9027/3a590316d2440dd63f7510f9238f24357b93bf61/'),
 '410':('Условия зачёта встречных требований','https://www.consultant.ru/document/cons_doc_LAW_5142/ce09e59d11f3a60c30a1601c0f6c7cceb9835dfa/'),
 '368':('Условия независимой гарантии','https://www.consultant.ru/document/cons_doc_LAW_5142/03edc46b2ef855fddfaaa3d77dac1d071ef3dba1/'),
 '371':('Отзыв и изменение гарантии','https://www.consultant.ru/document/cons_doc_LAW_5142/57bea654bf38c3b50efbfba87ea1f53b7cd090a9/'),
 '374':('Предъявление требования гаранту','https://www.consultant.ru/document/cons_doc_LAW_5142/d2b4e2d6a7f878c07420796abb37fe3d5823f0e9/'),
 '376':('Отказ и приостановление платежа гарантом','https://www.consultant.ru/document/cons_doc_LAW_5142/6a272c71c7c8b647b8b9d7eba71db4e01d901365/'),
 '753':('Сдача и приёмка строительных работ','https://www.consultant.ru/document/cons_doc_LAW_9027/6b2d751a0d605616a9a1012cb7c7fbac1b6d84b3/')}
def finish(d,lawids):
    # Replace the empty promotion block with actual navigation; preserve the guide structure.
    for p in list(d.paragraphs):
        if 'Переход к платному комплекту' in p.text or (not p.text.strip() and p==d.paragraphs[-1]):
            p._element.getparent().remove(p._element)
    while d.paragraphs and not d.paragraphs[-1].text.strip():d.paragraphs[-1]._element.getparent().remove(d.paragraphs[-1]._element)
    for p in list(d.paragraphs):
        if not p.text and not p._p.xpath('.//w:drawing|.//w:sectPr|.//w:br[@w:type="page"]'):
            p._element.getparent().remove(p._element)
    d.add_heading('Нормативные ориентиры',1)
    for k in lawids:
        p=d.add_paragraph();link(p,'ГК РФ статья '+k+' — '+LAWS[k][0],LAWS[k][1]);p.paragraph_format.space_after=Pt(3)
    p=d.add_paragraph('Сопоставьте нормы с условиями своего договора и документами по объекту. Для строительных работ без подписи второй стороны отдельно проверьте порядок сдачи, причины отказа и доказательства направления акта.')
    p=d.add_paragraph();link(p,'Полный комплект по авансу и расчётам','https://nastoronepodryadchika.ru/products/p8-avans-po-dogovoru-subpodryada.html')
    p=d.add_paragraph();link(p,'На стороне подрядчика','https://nastoronepodryadchika.ru');p.add_run('  |  ');link(p,'Telegram','https://t.me/nastoronepodryadchika')
    p=d.add_paragraph('Вопросы по файлам: nastoronepodryadchika@yandex.ru. Редакция 23.10.2026.')
    for name in ['Title','Heading 1','Heading 2','Heading 3']:
        st=d.styles[name];st.font.color.rgb=RGBColor(0,0,0)
        st.font.size=Pt(16 if name=='Title' else 12)
        st.font.name='Arial'
        for e in list(st.element.xpath('.//w:pBdr')):e.getparent().remove(e)
    d.styles['Normal'].font.name='Arial';d.styles['Normal'].font.size=Pt(11)
    for p in d.paragraphs:
        for r in p.runs:r.font.name='Arial'
        if p.style.name.startswith('Heading'):
            text=re.sub(r'Условие ([1-4])\. ',r'Условие \1 ',p.text).replace('Пятое, чего в договоре может не быть','Дополнительные условия договора').replace('Обеспечение: гарантия, поручительство, платёж','Обеспечение аванса')
            if text!=p.text:replace(p,text)
        if p.style.name=='Title':
            p.paragraph_format.space_after=Pt(10)
            if p._p.pPr is not None:
                for e in list(p._p.pPr):
                    if e.tag==qn('w:pBdr'):p._p.pPr.remove(e)
        if p.style.name.startswith('Heading')or p.style.name=='Title':
            p.paragraph_format.keep_with_next=True
            for r in p.runs:r.font.color.rgb=RGBColor(0,0,0);r.font.size=Pt(16 if p.style.name=='Title' else 12)
    for t in d.tables:
        pr=t._tbl.tblPr
        borders=pr.find(qn('w:tblBorders'))
        if borders is None:borders=OxmlElement('w:tblBorders');pr.append(borders)
        for edge in ['top','left','bottom','right','insideH','insideV']:
            e=borders.find(qn('w:'+edge))
            if e is None:e=OxmlElement('w:'+edge);borders.append(e)
            for key,value in [('val','single'),('sz','4'),('color','D9D9D9')]:e.set(qn('w:'+key),value)
        for i,row in enumerate(t.rows):
            trpr=row._tr.get_or_add_trPr()
            if trpr.find(qn('w:cantSplit')) is None:trpr.append(OxmlElement('w:cantSplit'))
            if i==0 and trpr.find(qn('w:tblHeader')) is None:trpr.append(OxmlElement('w:tblHeader'))
            for c in row.cells:
                c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
                cp=c._tc.get_or_add_tcPr();shade=cp.find(qn('w:shd'))
                if shade is None:shade=OxmlElement('w:shd');cp.append(shade)
                shade.set(qn('w:fill'),'343B40' if i==0 else ('F5F5F5' if i%2==0 else 'FFFFFF'))
                mar=cp.find(qn('w:tcMar'))
                if mar is None:mar=OxmlElement('w:tcMar');cp.append(mar)
                for edge in ['top','bottom','left','right']:
                    e=mar.find(qn('w:'+edge))
                    if e is None:e=OxmlElement('w:'+edge);mar.append(e)
                    e.set(qn('w:w'),'80');e.set(qn('w:type'),'dxa')
                for p in c.paragraphs:
                    p.paragraph_format.space_after=Pt(3)
                    p.paragraph_format.keep_with_next=False
                    for r in p.runs:r.font.size=Pt(10);r.font.name='Arial';r.font.color.rgb=RGBColor.from_string('FFFFFF' if i==0 else '222222');r.font.bold=(i==0)

name='01-proverochnyy-list-usloviy-avansa.docx';d=Document(BASE/'source'/name);first=len(changes)
par(d,0,'ПРОВЕРОЧНЫЙ','Проверочный лист условий аванса и обеспечения')
par(d,3,'Аванс','Аванс — предварительная оплата будущих работ. Его получение не означает, что прибыль уже заработана. Порядок зачёта аванса уменьшает последующие платежи за работы; обязательство по неотработанной части и доступный остаток денег нужно проверять отдельно.\n\nСопоставьте размер аванса, порядок погашения, обеспечение и основания возврата. Файл 02 разделяет удержанные и заблокированные деньги, фактические затраты, остаток аванса и стоимость непринятых работ. Единой суммы «денег не у вас» для этих разных величин нет.')
par(d,5,'Лист заполняется','Проверьте проект договора и приложения до подписания. Выпишите точные условия с номерами пунктов, затем оцените их влияние на расчёты по объекту.')
par(d,8,'Отдельно','Отметьте отсутствующие и противоречивые условия. Уточните их письменно: пробел в тексте не даёт второй стороне безусловного права установить любое правило.')
par(d,9,'Перенесите','Перенесите подтверждённые суммы на выбранную дату в файл 02. Сверяйте каждый вид отдельно и исключайте повторный учёт одного платежа.')
par(d,12,'Самое заметное','Проверьте сумму, базу процента, срок и условия выплаты. Размер аванса нужно сопоставлять с графиком его зачёта и затратами на обеспечение.')
par(d,15,'Условие, которое','Порядок погашения определяет, какая часть стоимости принятых работ будет оплачена новым платежом, а какая покрыта ранее выданным авансом. Проверьте каждый платёж по графику: сам зачёт аванса не является второй выплатой тех же денег.')
par(d,18,'То, чем','Разделяйте сумму гарантии, уплаченное вознаграждение банка и фактически заблокированное денежное покрытие. Номинал гарантии сам по себе не является расходом или изъятым остатком денег. Условия поручительства и обеспечительного платежа проверяются отдельно.')
par(d,21,'Пункт, который','При остановке или прекращении договора сверьте выданный аванс, зачтённые суммы и стоимость подтверждённых работ. Основание и срок возврата, состав неотработанной части и судьба обеспечения требуют отдельной проверки.')
par(d,24,'Отсутствующие','Проверьте, урегулированы ли следующие вопросы. Если условия нет, отметьте это и сопоставьте договор с применимыми нормами.')
par(d,25,'Порядок погашения','Порядок погашения аванса и способ отражения его зачёта в расчётах.')
par(d,27,'Право приостановить','Порядок уведомления при невыплате аванса и условия применения статей 328 и 719 ГК РФ.')
par(d,29,'Указание','Основания уменьшения платежа, порядок заявления зачёта встречных требований и документы для сверки расчёта.')
par(d,31,'Перенесите','Перенесите суммы в файл 02 и проверьте отдельные показатели. Для оценки кассового разрыва дополнительно нужен календарь поступлений и выплат, доступные деньги и обязательные платежи.')
cell(d,0,3,2,'Проверьте событие, срок, документ и зависимость выплаты от действий другой стороны. Неопределённое финансирование оставляет дату поступления денег неизвестной.')
cell(d,0,4,2,'Отсутствие отдельной фразы о приостановке не исключает защиту по закону. Проверьте встречность исполнения, препятствие работе, условия договора и порядок уведомления по статьям 328 и 719 ГК РФ.')
cell(d,1,1,2,'Уменьшает каждый платёж на согласованную долю. Проверьте базу, округление и предел погашения остатком аванса.')
cell(d,1,2,2,'Уменьшает первые платежи за работы. Сопоставьте их с уже полученным авансом и расходами по графику.')
cell(d,1,3,2,'Уменьшает окончательный платёж на ранее выданную сумму. Отдельно проверьте, хватит ли поступлений к этому моменту.')
cell(d,1,4,2,'Создаёт неопределённость расчётов. Попросите согласовать порядок; отсутствие пункта само по себе не означает право другой стороны определить его произвольно.')
cell(d,2,1,1,'У гарантии отдельно проверяются номинал, комиссия и покрытие; у поручительства — объём ответственности; у денежного обеспечения — сумма и условия возврата.')
cell(d,2,2,1,'Сверьте договор подряда и соглашение с банком: какие комиссии и продления оплачивает каждая сторона.')
cell(d,2,3,1,'Срок действия должен быть указан в независимой гарантии. Одной фразы «до полного исполнения» недостаточно для оценки срока и стоимости; проверьте документ банка и порядок продления.')
cell(d,2,4,1,'Установите основания продления, срок обращения в банк и распределение расходов при переносе работ.')
cell(d,2,5,1,'Безотзывность относится к отзыву и изменению гарантии. Для платежа проверяются условия гарантии, обстоятельства и документы требования; возможны основания отказа или приостановления по закону.')
cell(d,2,6,1,'Выпишите событие, подтверждающий документ и срок возврата. Если нужен акт второй стороны, уточните порядок при задержке его подписания.')
cell(d,3,2,1,'Ограничение расчёта только двусторонними актами создаёт риск спора о выполненном. Работы без подписи не обнуляются автоматически: нужны доказательства выполнения, сдачи и причин отказа.')
cell(d,3,4,1,'Сверьте требования по авансу с выплатами по обеспечению и последующими расчётами с банком. Уточните, как исключается повторное получение одной и той же суммы.')
